const gatePath='.superpowers/m74-hosted-gate-candidate2.json',migrationPath='.superpowers/m74-hosted-migration-candidate2.json'
const gateBytes=await Bun.file(gatePath).bytes(),migrationBytes=await Bun.file(migrationPath).bytes(),gate=JSON.parse(Buffer.from(gateBytes).toString()),migration=JSON.parse(Buffer.from(migrationBytes).toString())
const pinned={sql:'4486f83e2f2f6e5cb8db5991575a74f540b891eefd1ff65317801545c5b6c071',commit:'f5d7383e9624027d5169578012e261a789a268e8',upgrade:'7f5ec5a6d260687b9af6b84a2f6d1430e50c162ba0dd72bfc7f826ce9fdee5da',recovery:'21cb39a60aec8a2b87c0c8805c277acdc834a84fe092532ac888cbf1ba0e834e',forward:'36f1c0f3d5ec44f353139bc132576747a5f25230cc6c0173a0b2a62a66acf2dd'}
check(digest(await Bun.file('tools/staging/m74-upgrade.ts').bytes())===pinned.upgrade,'reviewed repaired upgrade bytes')
check(digest(await Bun.file('packages/neuvetra-database/src/migrations/0017_mobile_diesel.sql').bytes())===pinned.sql,'reviewed migration bytes')
const receipts:any={};for(const name of ['backup','restore','recovery','forwardRecovery']){const bytes=await Bun.file(gate[name+'Receipt']).bytes();check(digest(bytes)===gate[name+'ReceiptSha256'],'receipt file hash '+name);receipts[name]=JSON.parse(Buffer.from(bytes).toString())}
check(gate.recoveryReceiptSha256===pinned.recovery&&gate.forwardRecoveryReceiptSha256===pinned.forward,'independent reviewed receipt pins')
validateUpgradeGate(gate,receipts.backup,receipts.restore,receipts.recovery,receipts.forwardRecovery,Date.parse(migration.createdAt))
check(migration.status==='m74_migration_committed'&&migration.beforeVersion===16&&migration.schemaVersion===17,'committed16 to17')
check(migration.gateSha256===digest(gateBytes)&&migration.reviewedCommit===pinned.commit&&gate.reviewedCommit===pinned.commit&&migration.reviewedMigrationHash===pinned.sql,'exact approved gate commit and SQL')
check(migration.project===gate.project&&migration.backupArchiveSha256===receipts.backup.archiveSha256,'project archive binding')
check(canonical(migration.before)===canonical(receipts.backup.inventory),'actual locked before state equals backup')
const before=migration.before,after=migration.after,newTables=after.tables.filter((t:any)=>!before.tables.some((b:any)=>b.name===t.name))
const expected=['mobile_diesel_audit','mobile_diesel_evidence_reservations','mobile_diesel_fuel_statements','mobile_diesel_heads','mobile_diesel_mileage_statements','mobile_diesel_reports','mobile_diesel_requests','mobile_diesel_reviews','mobile_diesel_versions']
check(canonical(newTables.map((t:any)=>t.name).sort())===canonical(expected.sort())&&newTables.every((t:any)=>t.count===0&&t.rowHashes.length===0),'exact nine empty new tables')
const contains=(old:string[],next:string[])=>{const remaining=[...next];for(const hash of old){const at=remaining.indexOf(hash);check(at>=0,'retained multiset member');remaining.splice(at,1)}return remaining.length}
for(const table of before.tables){const now=after.tables.find((t:any)=>t.name===table.name);check(now,'retained table');check(now.count===table.count+(table.name==='schema_migrations'?1:0),'old table count preservation');check(now.rowHashes.length===now.count&&table.rowHashes.length===table.count,'actual counts match row-hash multiplicity');check(contains(table.rowHashes,now.rowHashes)===(table.name==='schema_migrations'?1:0),'only one migration receipt appended');if(table.name!=='schema_migrations')check(now.sha256===table.sha256,'old table full digest')}
check(canonical(Object.keys(before.catalogRowHashes).sort())===canonical(Object.keys(after.catalogRowHashes).sort()),'catalog kinds exact');let newCatalogEntries=0;for(const k of Object.keys(before.catalogRowHashes))newCatalogEntries+=contains(before.catalogRowHashes[k],after.catalogRowHashes[k])
for(const key of ['roles','memberships','defaultAcls','dependencies'])check(canonical(before[key])===canonical(after[key]),'preserved '+key)
check(migration.beforeContent.schemaVersion===16&&migration.afterContent.schemaVersion===17,'content schema boundary')
for(const [name,content]of [['before',migration.beforeContent],['after',migration.afterContent]]as const)check(digest(canonical(content.entries))===content.sha256,'actual content manifest digest '+name)
check(canonical(migration.beforeContent.entries)===canonical(migration.afterContent.entries)&&canonical(migration.beforeContent)===canonical(receipts.backup.recoveryManifest),'all content and explicit null preserved')
console.log(JSON.stringify({status:'m74_hosted_migration_receipts_independently_verified',migrationReceiptSha256:digest(migrationBytes),gateReceiptSha256:digest(gateBytes),commit:pinned.commit,migration:pinned.sql,beforeTables:before.tables.length,afterTables:after.tables.length,newTables:newTables.length,oldRows:before.tables.reduce((n:number,t:any)=>n+t.count,0),afterRows:after.tables.reduce((n:number,t:any)=>n+t.count,0),newCatalogEntries,preservedContentEntries:migration.beforeContent.entries.length,allReferencedReceiptHashesVerified:true,noDatabaseConnections:true,hostedExerciseAndRestartAcceptance:false}))
if(process.argv.includes('--journal')||process.argv.includes('--exercise-prefix')){
 const prefix=process.argv.includes('--exercise-prefix'),path='.superpowers/m74-hosted-journey.jsonl';if(!prefix)check(!await Bun.file(path+'.lock').exists(),'journey finished and unlocked')
 const parse=(text:string)=>{check(text.endsWith('\n'),'complete journal line');const entries=text.trimEnd().split('\n').map(line=>JSON.parse(line));let previous:string|null=null;for(const [i,e]of entries.entries()){const {sha256,...body}=e;check(e.sequence===i+1&&e.previousSha256===previous&&digest(canonical(body))===sha256,'independent journal chain');previous=sha256}return entries}
 const bytes=await Bun.file(path).bytes(),allEvents=parse(Buffer.from(bytes).toString()),prefixEnd=allEvents.findIndex(e=>e.mode==='exercise'&&e.kind==='attempt_finished'),events=prefix?allEvents.slice(0,prefixEnd+1):allEvents,prior=parse(await Bun.file('.superpowers/m73-hosted-journey.jsonl').text()),company=events[0]?.workspaceId
 check(events.length>0,'completed exercise prefix')
 check(events.every(e=>e.workspaceId===company),'single workspace journal')
 const starts=events.filter(e=>e.kind==='attempt_started'),finishes=events.filter(e=>e.kind==='attempt_finished')
 for(const start of starts){const matches=finishes.filter(e=>e.data.attemptSequence===start.sequence);check(matches.length===1&&matches[0].data.status==='passed'&&matches[0].data.allCreatedAuthSessionsClosed===true,'closed successful attempt')}
 const base=events.find(e=>e.kind==='baseline'),success=events.find(e=>e.kind==='exercise_complete'),revisits=events.filter(e=>e.kind==='revisit_verified');check(base&&success&&(prefix||revisits.length>0),'baseline exercise and revisit present')
 check(revisits.every(e=>e.data.exerciseSha256===success.sha256),'revisit exact completed exercise pin')
 const intents=events.filter(e=>e.kind==='post_intent'),outcomes=events.filter(e=>e.kind==='post_outcome');check(intents.length===11&&outcomes.length===11,'exact bounded attempted operations')
 const names=new Set<string>();for(const intent of intents){check(!names.has(intent.data.name),'no duplicate operation');names.add(intent.data.name);const matches=outcomes.filter(e=>e.data.name===intent.data.name);check(matches.length===1&&matches[0].sequence>intent.sequence&&matches[0].data.status===intent.data.expected&&matches[0].data.route===intent.data.route&&matches[0].data.role===intent.data.role,'every post outcome bound to intent');if(intent.data.expected!==201)check(!Object.hasOwn(matches[0].data,'response'),'refusal stores no raw private response')}
 check(outcomes.filter(e=>e.data.status===201).length===6,'six admitted bounded writes')
 for(const done of finishes)check(done.data.applicationPostRequests===(done.mode==='exercise'?11:0),'baseline and revisit zero writes')
 for(const e of events.filter(e=>e.kind==='actual_readiness'))check(e.data.schemaVersion===(e.mode==='baseline'?16:17),'actual readiness schema')
 const register=await decodeMobileRegister(success.data.register,company),corporate=await decodeCorporateRegister(success.data.corporate,company),originalCorporate=await decodeCorporateRegister(base.data.corporate,company)
 check(register.worksheets.length===1,'one hosted vehicle');const worksheet=register.worksheets[0]!;check(worksheet.versions.length===2&&worksheet.reports.length===2,'two versions and reports')
 const [first,second]=worksheet.versions;check(first!.calculation?.total.unrounded==='10351.53209375'&&second!.calculation?.total.unrounded==='10357.37584375','exact hosted calculated totals');check(first!.review?.decision==='accepted_bounded_internal'&&second!.review===null,'historical review and unreviewed correction');check(second!.findings.some(f=>f.code==='mileage_activity_statement_discrepancy'),'open correction discrepancy')
 const obs=(s:string)=>({sha256:digest(s),byteLength:Buffer.byteLength(s)}),expectedDownloads:Record<string,unknown>={}
 for(const version of worksheet.versions){expectedDownloads['version_'+version.id]=obs(m74Export(version));for(const [kind,statement]of [['fuel',version.fuelStatement],['mileage',version.mileageStatement]]as const)if(statement)expectedDownloads[kind+'_'+statement.id]=obs(statement.text)}
 for(const report of worksheet.reports)expectedDownloads['report_'+report.id]=obs(report.html)
 check(canonical(expectedDownloads)===canonical(success.data.downloads),'independent exact mobile download fingerprints')
 for(const v of originalCorporate.versions)check(canonical(corporate.versions.find(x=>x.id===v.id))===canonical(v),'old corporate versions unchanged')
 const priorSuccess=prior.find(e=>e.kind==='exercise_complete');check(priorSuccess,'prior gas journal complete');const gas=await decodeGasRegister(base.data.priorGas.register,company),expectedGas:Record<string,unknown>={};for(const w of gas.worksheets){for(const v of w.versions){expectedGas['version_'+v.id]=obs(m73Export(v));if(v.statement)expectedGas['statement_'+v.statement.id]=obs(v.statement.text)}for(const r of w.reports)expectedGas['report_'+r.id]=obs(r.html)}
 check(canonical(expectedGas)===canonical(base.data.priorGas.downloads)&&canonical(expectedGas)===canonical(priorSuccess.data.downloads),'exact prior gas download fingerprints')
 check(canonical(base.data.legacy)===canonical(prior.find(e=>e.kind==='baseline').data.legacy),'legacy baseline preserved')
 if(!prefix){const restartBytes=await Bun.file('.superpowers/m74-hosted-restart.json').bytes(),restart=JSON.parse(Buffer.from(restartBytes).toString()),exerciseFinish=finishes.find(e=>e.mode==='exercise'),revisitStart=starts.find(e=>e.mode==='revisit');check(restart.status==='m74_actual_service_restart_observed'&&restart.restartMutationAcknowledged===true&&restart.deploymentStatus==='SUCCESS'&&restart.commit===pinned.commit&&restart.deploymentId==='b849d413-6a8a-406c-bf3e-73dd71137117'&&restart.image==='sha256:9c4af30f3ff54ee40f6eecd833cca2774bdc7fd67787b045ca65d52ab244c306','exact root-observed restart identity');check(restart.ready.status==='ready'&&restart.ready.schemaVersion===17&&restart.ready.legacyContainmentVerified===true,'post-restart readiness');check(Date.parse(restart.observedAt)>Date.parse(exerciseFinish.createdAt)&&Date.parse(revisitStart.createdAt)>Date.parse(restart.observedAt),'revisit follows actual restart');console.log(JSON.stringify({status:'m74_actual_restart_receipt_bound',restartReceiptSha256:digest(restartBytes),deploymentId:restart.deploymentId,image:restart.image,observedAt:restart.observedAt,revisitBeganAt:revisitStart.createdAt}))}
 const downloadPath=process.argv.find(arg=>arg.startsWith('--download='))?.slice('--download='.length)
 if(downloadPath){const actual=await Bun.file(downloadPath).bytes(),report=worksheet.reports.find(r=>r.id==='1f04dfbf-5eb7-4269-84dc-ac7425ac04d6');check(report&&report.decisionId!==null&&Buffer.from(actual).equals(Buffer.from(report.html)),'actual browser download byte-equals retained reviewed HTML');console.log(JSON.stringify({status:'m74_actual_browser_download_independently_verified',sha256:digest(actual),byteLength:actual.length,reportId:report.id}))}
 console.log(JSON.stringify({status:prefix?'m74_hosted_exercise_prefix_independently_verified':'m74_hosted_journal_independently_verified',journalSha256:prefix?null:digest(bytes),journalTail:events.at(-1).sha256,events:events.length,attempts:starts.length,applicationPostRequests:intents.length,admittedWrites:6,permissionRefusals:5,mobileDownloadCount:Object.keys(expectedDownloads).length,priorGasDownloadCount:Object.keys(expectedGas).length,revisits:revisits.length,exactTotals:[first!.calculation!.total.unrounded,second!.calculation!.total.unrounded],allCreatedSessionsClosed:true,noNetworkOrDatabaseConnections:true,actualRestartReceiptBound:!prefix}))
